    delta={'A':(-1,0),'W':(0,1),'S':(0,-1),'D':(1,0)}
    Characters[index].ChangePosition(*delta[move])
    character=Characters[index]
    print(character.GetName(),'has changed coordinates to X =',character.GetX(),'and Y =',character.GetY())
